INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('gamma-app', 'Gamma App', 'AI-powered presentations, slides, and websites generated in seconds.', 'AI/ML', 'Gamma Tech', 'Proprietary', 'Freemium', 1, 'Free tier with 400 initial AI credits; Plus plan at $10/mo, Pro at $20/mo', 0, 'v2.8', 'Exceptional automated slide design and layout polish,Instant interactive widgets, cards, and embeds,One-click export to PDF and PPTX,Generates cohesive theme palettes', 'Limited granular pixel-level shape editing,AI credits get consumed quickly on free plan,No public REST API for automated generation', 'Web,Mobile Web', 'https://gamma.app', 'https://help.gamma.app', NULL, '2026-09-28 14:30 UTC');
INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('marp', 'Marp (Markdown Presentation)', 'The open-source Markdown presentation ecosystem for developers.', 'DevTools', 'Marp Community', 'MIT (Open Source)', 'Open Source', 1, '100% Free and Open Source forever', 1, 'v3.8.0', 'Write presentations entirely in Markdown with zero lock-in,Version control presentations in Git like code,Exports to PDF, PPTX, and HTML,VS Code extension with instant live preview', 'No automated AI graphic/text generation out of the box,Requires Markdown and basic CSS knowledge for custom themes,Not suited for non-technical users', 'VS Code,CLI,Web', 'https://marp.app', 'https://marpit.marp.app', 'https://github.com/marp-team/marp', '2026-09-28 13:45 UTC');
INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('nextjs', 'Next.js', 'The React framework for the web with Server Components and static optimization.', 'Frontend', 'Vercel', 'MIT (Open Source)', 'Open Source', 1, 'Open Source framework free; Vercel Hobby hosting is free with generous limits', 1, 'v15.0.0', 'React 19 support with Server Components and Server Actions,Turbopack bundler for fast local development,Optimized image, font, and script loaders,Flexible routing with App Router', 'Steep learning curve around App Router caching semantics,Deeply tied to Vercel deployment primitives', 'Node.js,Docker,Vercel,AWS', 'https://nextjs.org', 'https://nextjs.org/docs', 'https://github.com/vercel/next.js', '2026-09-28 13:50 UTC');
INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('python', 'Python', 'Versatile high-level programming language dominating AI, ML, and automation.', 'DevTools', 'Python Software Foundation', 'PSF License (Open Source)', 'Open Source', 1, '100% Free and Open Source', 1, '3.13.0', 'De facto industry standard for AI, PyTorch, TensorFlow, and data science,Massive PyPI package ecosystem,Experimental free-threaded (no-GIL) build in Python 3.13,Clear and readable syntax', 'Slower raw execution speed compared to C++/Rust/Go (mitigated by JIT),Packaging and virtual environment tooling fragmentation historically', 'Cross-platform,Linux,Mac,Windows,WebAssembly', 'https://www.python.org', 'https://docs.python.org/3/', 'https://github.com/python/cpython', '2026-09-28 15:10 UTC');
INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('qdrant', 'Qdrant', 'High-performance vector search engine & database written in Rust.', 'Databases', 'Qdrant Technologies', 'Apache 2.0 (Open Source)', 'Open Source', 1, '100% Free self-hosted; Managed Qdrant Cloud has 1GB free tier cluster', 1, 'v1.12.1', 'Ultra-fast Rust vector indexing with payload-based filtering,Native quantization (scalar, product, binary) cutting RAM by up to 90%,Hybrid dense/sparse search built-in,Distributed cluster clustering support', 'Requires understanding of vector embeddings and distance metrics,Memory footprint requires tuning for very large scale', 'Docker,Kubernetes,Linux,Mac,Cloud', 'https://qdrant.tech', 'https://qdrant.tech/documentation', 'https://github.com/qdrant/qdrant', '2026-09-28 14:20 UTC');
INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('slidesai', 'SlidesAI', 'AI Google Slides extension that converts raw text into organized slide decks.', 'AI/ML', 'SlidesAI.io', 'Proprietary', 'Freemium', 1, 'Free basic tier (3 presentations/mo up to 2500 characters input); Pro at $10/mo', 0, 'v3.1', 'Runs directly inside Google Slides as an add-on,Great for academic summaries and rapid bullet point formatting,Generates topic-relevant Unsplash images automatically,Multilingual text input support (100+ languages)', 'Designs are relatively standard and basic,Short character limits on free tier,Dependent on Google Workspace ecosystem', 'Google Slides Add-on,Web', 'https://www.slidesai.io', 'https://docs.slidesai.io', NULL, '2026-09-28 14:00 UTC');
INSERT OR REPLACE INTO technologies (id, name, tagline, category, developer, license, pricing_model, has_free_tier, pricing_details, has_api, current_version, strengths, limitations, platforms, official_url, docs_url, repo_url, last_verified_at) VALUES ('supabase', 'Supabase', 'Open-source Firebase alternative powered by PostgreSQL and pgvector.', 'Databases', 'Supabase Inc.', 'Apache 2.0 (Open Source)', 'Freemium', 1, 'Free tier includes 500MB database, 50k monthly active users, 1GB storage; Pro at $25/mo', 1, 'PostgreSQL 15.6 / Supabase 2.0', 'Standard PostgreSQL with zero proprietary lock-in,Built-in auth, real-time WebSocket subscriptions, storage, and edge functions,Native pgvector extension for AI embeddings,Self-hostable with single Docker compose', 'Free tier databases pause after 7 days of inactivity,Complex relational schema migrations require SQL proficiency', 'Web,Docker,Self-hosted', 'https://supabase.com', 'https://supabase.com/docs', 'https://github.com/supabase/supabase', '2026-09-28 14:10 UTC');
INSERT OR REPLACE INTO events (id, technology_id, technology_name, title, category, event_type, importance, summary_tldr, what_changed, explanation_technical, explanation_simple, impact_audiences, impact_summary, primary_source_tier, sources_count, sources, verified_at, is_confirmed) VALUES ('evt-security-openssl-cve-2026', NULL, 'OpenSSL', 'Critical Internet Security Patch Released: Prevents Attackers from Remotely Crashing Web Servers', 'Security', 'security_patch', 'critical', 'An emergency security fix was released for OpenSSL to patch a dangerous loophole that malicious actors could use to crash web servers worldwide. Server owners must update immediately.', '[object Object]', 'CVE-2026-4819 involves improper state validation when processing truncated ServerKeyExchange structures during post-handshake client authentication in TLS 1.3, allowing remote denial-of-service crashes.', '💡 Everyday Analogy: Imagine a building security door lock that would jam and lock everyone out if someone jiggled the handle in an unusual way. The lock manufacturer just distributed a free emergency replacement lock so the building stays protected.', 'Website Owners,Cloud Engineers,System Administrators,IT Security Teams', 'Immediate free security patch needed for websites and web servers to prevent crashes.', '1', '11', '[object Object],[object Object]', '2026-10-01 10:05 UTC', 1);
INSERT OR REPLACE INTO events (id, technology_id, technology_name, title, category, event_type, importance, summary_tldr, what_changed, explanation_technical, explanation_simple, impact_audiences, impact_summary, primary_source_tier, sources_count, sources, verified_at, is_confirmed) VALUES ('evt-python-3-13', 'python', 'Python', 'Python Unlocks True Multi-Core Speed: Heavy AI & Data Calculations Now Run Simultaneously', 'DevTools', 'major_upgrade', 'critical', 'For the first time in 30 years, Python can now use all of your computer processor cores at once without freezing. It also introduced a friendlier, colorful interactive command screen.', '[object Object]', 'PEP 703 enables a free-threaded build of CPython 3.13 without the Global Interpreter Lock (GIL). Introduces thread-safe reference counting and mimalloc heap isolation. A Tier 2 copy-on-write JIT translates bytecode into machine code, and PyRepl provides full multiline colored interactive terminal capabilities.', '💡 Everyday Analogy: Think of this like widening a congested 1-lane road into an 8-lane expressway. Previously, no matter how powerful your laptop was, Python forced all work through a single lane. Now, all your computer cores work together simultaneously. Your AI models and big spreadsheets finish in a fraction of the time.', 'Anyone learning Python,AI Researchers,Data Analysts,Software Engineers', 'Your computer can finally run multiple heavy tasks at once without slowing to a crawl.', '1', '8', '[object Object],[object Object],[object Object]', '2026-10-01 09:47 UTC', 1);
INSERT OR REPLACE INTO events (id, technology_id, technology_name, title, category, event_type, importance, summary_tldr, what_changed, explanation_technical, explanation_simple, impact_audiences, impact_summary, primary_source_tier, sources_count, sources, verified_at, is_confirmed) VALUES ('evt-qdrant-quantization-v112', 'qdrant', 'Qdrant', 'AI Search Memory Breakthrough: Cloud Server Memory Slashed by 95% to Cut Hosting Bills', 'Databases', 'major_upgrade', 'major', 'A new memory compression algorithm allows AI search engines and chatbots to store millions of documents in just 5% of the memory previously required, saving huge cloud hosting costs.', '[object Object]', 'Qdrant 1.12 implements 2-bit binary quantization with hardware SIMD bitwise hamming distance acceleration. Compresses float32 embeddings down to 2 bits per dimension with an automatic oversampling rescore pipeline.', '💡 Everyday Analogy: Imagine an entire room full of bulky metal filing cabinets compressed down into a single shoebox, without misplacing a single piece of paper. You can now build massive AI knowledge bases for pennies on budget servers.', 'AI App Developers,Startups on a budget,Students building chatbot projects', 'Drastically lowers the cost of running AI knowledge bases and semantic search tools.', '1', '6', '[object Object],[object Object]', '2026-10-01 09:29 UTC', 1);
INSERT OR REPLACE INTO events (id, technology_id, technology_name, title, category, event_type, importance, summary_tldr, what_changed, explanation_technical, explanation_simple, impact_audiences, impact_summary, primary_source_tier, sources_count, sources, verified_at, is_confirmed) VALUES ('evt-gamma-export-v28', 'gamma-app', 'Gamma App', 'Gamma Now Exports AI Slides Directly into PowerPoint as Fully Editable Text & Shapes', 'AI/ML', 'feature_update', 'significant', 'You can now create an entire presentation with AI in Gamma and export it directly to PowerPoint with all text boxes, charts, and fonts staying 100% editable.', '[object Object]', 'Gamma rebuilt their export pipeline to compile native OpenXML presentation primitives directly instead of SVG rasterization. This enables round-trip PowerPoint interoperability while preserving dynamic cards, nested tables, and column flex ratios.', '💡 Everyday Analogy: Imagine previously receiving a scanned photocopy where you couldn''t fix typos or change colors. With this update, you receive an actual editable Word document. You get the 10-second speed of AI generation plus the full editing freedom of PowerPoint.', 'Students making class presentations,Startup founders pitching investors,Sales teams & Marketers', 'You no longer have to choose between AI generation speed and PowerPoint compatibility; drafts take 10 seconds and stay fully editable.', '1', '5', '[object Object],[object Object]', '2026-10-01 09:17 UTC', 1);
INSERT OR REPLACE INTO events (id, technology_id, technology_name, title, category, event_type, importance, summary_tldr, what_changed, explanation_technical, explanation_simple, impact_audiences, impact_summary, primary_source_tier, sources_count, sources, verified_at, is_confirmed) VALUES ('evt-cursor-composer-v041', 'cursor', 'Cursor', 'Cursor AI Can Now Code Quietly in Background & Fix Its Own Mistakes Before Showing You', 'DevTools', 'feature_update', 'major', 'Instead of waiting for an AI to write code line by line, you can assign it a large task across multiple files. It tests its own code silently and only shows you a clean, working preview.', '[object Object]', 'Cursor Composer executes within an isolated git worktree branch, running test runners and LSP diagnostics. If a syntax or type error is detected, the agent feeds the diagnostic back into context for up to 3 self-correction iterations.', '💡 Everyday Analogy: Like handing a junior assistant a complex assignment to finish at their own desk, rather than having them hover over your shoulder typing. They complete the assignment, check for typos themselves, and only present you with the final clean draft.', 'Programmers,Freelancers,Computer Science Students,Solo Founders', 'Saves hours of tedious repetitive work when updating websites or refactoring multiple files.', '1', '7', '[object Object]', '2026-10-01 09:05 UTC', 1);
INSERT OR REPLACE INTO events (id, technology_id, technology_name, title, category, event_type, importance, summary_tldr, what_changed, explanation_technical, explanation_simple, impact_audiences, impact_summary, primary_source_tier, sources_count, sources, verified_at, is_confirmed) VALUES ('evt-hist-gamma-app-01', 'gamma-app', 'Gamma App', 'Minor Quality-of-Life Improvements in Gamma App v2.4', 'AI/ML', 'feature_update', 'normal', 'The team shipped a batch of small but noticeable improvements to Gamma App v2.4: faster startup times, cleaner error messages, and a handful of accessibility fixes.', '[object Object]', 'Release v2.4 of Gamma App. Routine upstream maintenance: dependency bumps, targeted performance tuning, and regression fixes validated against the project''s own test suite.', '💡 Everyday Analogy: This is like getting a routine service and oil change for your Gamma App — nothing flashy, but it keeps the engine running smoothly and quietly.', 'AI Engineers,Product Teams,Startups,Researchers', 'Keeps Gamma App on a supported, stable baseline for teams already using v2.4.', '1', '2', '[object Object],[object Object]', '2026-09-29 23:00 UTC', 1);
